executed_script:
$ErrorActionPreference = 'Stop'
$workspace = [IO.Path]::GetFullPath('C:\public\project-hyle\hyle')
$stage = [IO.Path]::GetFullPath('C:\public\project-hyle\hyle\.scratch\architecture-refactor-2026-10-18\gguf-nvfp4')
$planPath = 'C:\public\project-hyle\hyle\.scratch\architecture-refactor-2026-10-18\gguf-nvfp4\cleanup-plan.json'
if ((Get-FileHash -LiteralPath $planPath -Algorithm SHA256).Hash.ToLowerInvariant() -ne '50149b6538e9b09ea6522efa679a2d7efeceec8a89948bf3203370cb951fba7a') { throw 'Cleanup plan changed' }
$plan = Get-Content -LiteralPath $planPath -Raw | ConvertFrom-Json
$prefix = $stage.TrimEnd('\') + '\'
if (-not $stage.StartsWith($workspace.TrimEnd('\') + '\', [StringComparison]::OrdinalIgnoreCase)) { throw 'Stage outside workspace' }
# Verify every exact target before any deletion. File-only, never recursive.
foreach ($row in $plan.targets) {
    $target = [IO.Path]::GetFullPath([string]$row.path)
    if (-not $target.StartsWith($prefix, [StringComparison]::OrdinalIgnoreCase)) { throw "Target outside stage: $target" }
    $item = Get-Item -LiteralPath $target -Force
    if ($item.PSIsContainer -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)) { throw "Not an ordinary file: $target" }
    if ($item.Length -ne $row.bytes -or (Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash.ToLowerInvariant() -ne $row.sha256) { throw "Target identity changed: $target" }
}
foreach ($row in $plan.retained_images) {
    if ((Get-FileHash -LiteralPath $row.path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $row.sha256) { throw 'Retained image changed' }
}
$deleted = @()
foreach ($row in $plan.targets) {
    Remove-Item -LiteralPath $row.path -Force
    $deleted += [pscustomobject]@{ path=$row.path; bytes=$row.bytes; sha256=$row.sha256 }
}
$result = [pscustomobject]@{ passed=$true; files=$deleted.Count; bytes=($deleted | Measure-Object -Property bytes -Sum).Sum; deleted=$deleted; recursive=$false }
$result | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath 'C:\public\project-hyle\hyle\.scratch\architecture-refactor-2026-10-18\gguf-nvfp4\cleanup-result.json' -Encoding UTF8
$result | Select-Object passed,files,bytes | Format-List
